// ---- Envelope (Appendix C) ----
export type EnvelopeKind = "req" | "res" | "evt";

export interface ProtoError { code: string; message: string; }

export interface Envelope {
  v: number;
  id: string;
  kind: EnvelopeKind;
  name: string;
  seq?: number;
  payload: unknown;
  error?: ProtoError;
}

/** Build a request envelope. Unknown `name`s are allowed here -- the
 * core rejects them fail-fast at runtime (mirrors Rust FromStr). */
export function makeRequest(name: CommandName, payload: unknown, id: string): Envelope {
  return { v: PROTOCOL_VERSION, id, kind: "req", name, payload: payload ?? {} };
}

/** Parse + version-gate an envelope. Unknown fields are ignored;
 * unknown protocol versions throw (fail fast, Appendix C). */
export function parseEnvelope(raw: unknown): Envelope {
  if (typeof raw !== "object" || raw === null) throw new Error("proto: envelope must be an object");
  const o = raw as Record<string, unknown>;
  if (o["v"] !== PROTOCOL_VERSION)
    throw new Error(`proto: unsupported version ${String(o["v"])} (want ${PROTOCOL_VERSION})`);
  if (typeof o["id"] !== "string") throw new Error("proto: envelope.id must be a string");
  if (o["kind"] !== "req" && o["kind"] !== "res" && o["kind"] !== "evt")
    throw new Error("proto: envelope.kind must be req|res|evt");
  if (typeof o["name"] !== "string") throw new Error("proto: envelope.name must be a string");
  return {
    v: PROTOCOL_VERSION,
    id: o["id"] as string,
    kind: o["kind"] as EnvelopeKind,
    name: o["name"] as string,
    ...(typeof o["seq"] === "number" ? { seq: o["seq"] as number } : {}),
    // A null payload is meaningful (e.g. `setting_get` for an unset key:
    // the UI distinguishes null from an object). Only a missing payload
    // defaults to `{}`.
    payload: o["payload"] === undefined ? {} : o["payload"],
    ...(typeof o["error"] === "object" && o["error"] !== null
      ? { error: o["error"] as ProtoError } : {}),
  };
}

